$ErrorActionPreference='Stop'
$chrome='C:\Program Files\Google\Chrome Dev\Application\chrome.exe';$root='C:\Users\user\Desktop\Slide show'
foreach($spec in @(@(9243,'final-tv',1920,1080),@(9244,'final-mobile',390,844),@(9245,'final-desktop',1440,900))){$profile=Join-Path $root ('.tools\browser-profiles\'+$spec[1]);New-Item -ItemType Directory -Force -Path $profile|Out-Null;& $chrome '--headless=new' '--remote-allow-origins=*' ("--remote-debugging-port="+$spec[0]) ("--user-data-dir="+$profile) ("--window-size="+$spec[2]+','+$spec[3]) '--no-first-run' 'https://thebekal.com/'}
Start-Sleep -Seconds 6
function Call-Cdp($ws,[int]$id,$method,$params=@{}) { $s=[Net.WebSockets.ClientWebSocket]::new();$s.ConnectAsync([uri]$ws,[Threading.CancellationToken]::None).GetAwaiter().GetResult();try{$b=[Text.Encoding]::UTF8.GetBytes((@{id=$id;method=$method;params=$params}|ConvertTo-Json -Compress -Depth 8));[void]$s.SendAsync([ArraySegment[byte]]::new($b),[Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult();do{$m=[IO.MemoryStream]::new();do{$buf=New-Object byte[] 65536;$r=$s.ReceiveAsync([ArraySegment[byte]]::new($buf),[Threading.CancellationToken]::None).GetAwaiter().GetResult();$m.Write($buf,0,$r.Count)}while(-not $r.EndOfMessage);$o=([Text.Encoding]::UTF8.GetString($m.ToArray())|ConvertFrom-Json)}while($o.id -ne $id);return $o}finally{$s.Dispose()}}
function PageWs($port){$pages=(Invoke-WebRequest -UseBasicParsing "http://127.0.0.1:$port/json").Content|ConvertFrom-Json;$page=$pages|Where-Object {$_.type -eq 'page' -and $_.url -like 'https://thebekal.com/*'}|Select-Object -First 1; return [string]$page.webSocketDebuggerUrl}
function Eval($ws,$js){(Call-Cdp $ws 1 'Runtime.evaluate' @{expression=$js;awaitPromise=$true;returnByValue=$true}).result.result.value}
$a=PageWs 9243;$b=PageWs 9244;$c=PageWs 9245;if(!$a -or !$b -or !$c){throw 'Three public browser clients are required'}; if($a -is [array] -or $b -is [array] -or $c -is [array]){throw "Invalid debugger endpoints: A=$a B=$b C=$c"}
$stamp=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();$title="CODEX-LIVE-TEST-$stamp"
Eval $b "(async()=>{switchView('admin');currentDayIndex=0;document.getElementById('task-title').value='$title';document.getElementById('task-time').value='12:00 PM';await handleAddTask({preventDefault(){}});return JSON.stringify(tasksData.Saturday.find(t=>t.title==='$title'))})()" | Out-Null
function WaitFor($ws,$expression){for($i=0;$i -lt 30;$i++){if((Eval $ws $expression) -eq $true){return $true};Start-Sleep -Milliseconds 250};return $false}
$seenA=WaitFor $a "Object.values(tasksData).flat().some(t=>t.title==='$title')";$seenC=WaitFor $c "Object.values(tasksData).flat().some(t=>t.title==='$title')";if(!$seenA -or !$seenC){throw 'Live create did not reach all clients'}
$id=Eval $b "Object.values(tasksData).flat().find(t=>t.title==='$title').id";Eval $b "(async()=>{await toggleTaskStatus($id);return true})()"|Out-Null
$updatedA=WaitFor $a "Object.values(tasksData).flat().some(t=>t.id==$id&&t.status==='completed')";$updatedC=WaitFor $c "Object.values(tasksData).flat().some(t=>t.id==$id&&t.status==='completed')";if(!$updatedA -or !$updatedC){throw 'Live update did not reach all clients'}
Eval $b "(async()=>{await deleteTask($id);return true})()"|Out-Null
$deletedA=WaitFor $a "!Object.values(tasksData).flat().some(t=>t.id==$id)";$deletedC=WaitFor $c "!Object.values(tasksData).flat().some(t=>t.id==$id)";if(!$deletedA -or !$deletedC){throw 'Live delete did not reach all clients'}
[pscustomobject]@{Title=$title;LiveCreate=$seenA -and $seenC;LiveUpdate=$updatedA -and $updatedC;LiveDelete=$deletedA -and $deletedC;ClientA='1920x1080';ClientB='390x844';ClientC='1440x900'}|ConvertTo-Json
